[{"location":"api/#API-Documentation-for-PormG","page":"API","title":"API Documentation for PormG","text":"","category":"section"},{"location":"api/#Overview","page":"API","title":"Overview","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"The PormG module provides a set of abstractions and functions for working with SQL databases in Julia. It includes various types for SQL operations, models, and migrations, along with utilities for querying and manipulating data.","category":"page"},{"location":"api/#Exported-Functions","page":"API","title":"Exported Functions","text":"","category":"section"},{"location":"api/#object","page":"API","title":"object","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Retrieves an object from the database.\nUsage: object(...)","category":"page"},{"location":"api/#show_query","page":"API","title":"show_query","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Displays the SQL query that will be executed.\nUsage: show_query(...)","category":"page"},{"location":"api/#list","page":"API","title":"list","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Lists records from the database.\nUsage: list(...)","category":"page"},{"location":"api/#bulk_insert","page":"API","title":"bulk_insert","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Inserts multiple records into the database in a single operation.\nUsage: bulk_insert(...)","category":"page"},{"location":"api/#bulk_update","page":"API","title":"bulk_update","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Updates multiple records in the database in a single operation.\nUsage: bulk_update(...)","category":"page"},{"location":"api/#delete","page":"API","title":"delete","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Deletes records from the database.\nUsage: delete(...)","category":"page"},{"location":"api/#do_count","page":"API","title":"do_count","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Counts the number of records that match a query.\nUsage: do_count(...)","category":"page"},{"location":"api/#do_exists","page":"API","title":"do_exists","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Checks if any records exist that match a query.\nUsage: do_exists(...)","category":"page"},{"location":"api/#Abstract-Types","page":"API","title":"Abstract Types","text":"","category":"section"},{"location":"api/#PormGAbstractType","page":"API","title":"PormGAbstractType","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: The base abstract type for all types in the PormG module.","category":"page"},{"location":"api/#SQLConn","page":"API","title":"SQLConn","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Represents a connection to a SQL database.","category":"page"},{"location":"api/#SQLObject","page":"API","title":"SQLObject","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Represents an object that can be stored in the database.","category":"page"},{"location":"api/#SQLObjectHandler","page":"API","title":"SQLObjectHandler","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Handles operations related to SQL objects.","category":"page"},{"location":"api/#SQLTableAlias","page":"API","title":"SQLTableAlias","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Manages table aliases in SQL queries.","category":"page"},{"location":"api/#SQLInstruction","page":"API","title":"SQLInstruction","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Represents an instruction to build a SQL query.","category":"page"},{"location":"api/#SQLType","page":"API","title":"SQLType","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Base type for SQL-related types.","category":"page"},{"location":"api/#SQLTypeField","page":"API","title":"SQLTypeField","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Description: Represents a field to be used in SQL queries.","category":"page"},{"location":"api/#Usage-Examples","page":"API","title":"Usage Examples","text":"","category":"section"},{"location":"api/#Connecting-to-a-Database","page":"API","title":"Connecting to a Database","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"conn = SQLConn(...)  # Create a connection to the database","category":"page"},{"location":"api/#Inserting-Records","page":"API","title":"Inserting Records","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"bulk_insert(conn, data)  # Insert multiple records","category":"page"},{"location":"api/#Querying-Records","page":"API","title":"Querying Records","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"results = list(conn, query)  # Retrieve records based on a query","category":"page"},{"location":"api/#Conclusion","page":"API","title":"Conclusion","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"This documentation provides an overview of the API for the PormG module. For more detailed information on each function and type, please refer to the source code and additional documentation files.","category":"page"},{"location":"api/#API-Reference","page":"API","title":"API Reference","text":"","category":"section"},{"location":"api/","page":"API","title":"API","text":"Modules = [PormG, PormG.QueryBuilder, PormG.Models]\nOrder   = [:function, :type]","category":"page"},{"location":"api/#PormG.QueryBuilder.Count-Tuple{Any}","page":"API","title":"PormG.QueryBuilder.Count","text":"Count(x; distinct::Bool = false)\n\nCreates an aggregate COUNT function object for use in query building.\n\nArguments\n\nx: The column or expression to count.\ndistinct::Bool = false: If true, counts only distinct values of x.\n\nExamples\n\n```julia\n\nCount just when othermodelid is distinct\n\nquery = MyModels.modeltest |> object; query.filter(\"id__@gte\" => 1) query.values(\"id\", \"count\" => Count(\"othermodel_id\", distinct=true)) df = query |> list |> DataFrame\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.Q-Tuple","page":"API","title":"PormG.QueryBuilder.Q","text":"Q(x...)\n\nCreate a QObject with the given filters.   Ex.:   julia   a = object(\"tb_user\")   a.filter(Q(\"name\" => \"John\", Qor(\"age\" => 18, \"age\" => 19)))\n\nArguments:\n\nx: A list of key-value pairs or Qor(x...) or Q(x...) objects.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.Qor-Tuple","page":"API","title":"PormG.QueryBuilder.Qor","text":"Qor(x...)\n\nCreate a QorObject from the given arguments. The QorObject represents a disjunction of SQLTypeQ or SQLTypeQor objects.\n\nEx.:   julia   a = object(\"tb_user\")   a.filter(Qor(\"name\" => \"John\", Q(\"age__gte\" => 18, \"age__lte\" => 19)))\n\nArguments\n\nx...: A variable number of arguments. Each argument can be either a SQLTypeQ or SQLTypeQor object, or a Pair object.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder._determine_join_type-Tuple{PormG.PormGField}","page":"API","title":"PormG.QueryBuilder._determine_join_type","text":"build a row to join\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder._get_pair_to_oper-Union{Tuple{Pair{Vector{String}, T}}, Tuple{T}} where T<:Union{Integer, String}","page":"API","title":"PormG.QueryBuilder._get_pair_to_oper","text":"getpairtooper(x::Pair)\n\nConverts a Pair object to an OperObject. If the Pair's key is a string, it checks if it contains an operator suffix (e.g. \"@gte\", \"@lte\") and returns an OperObject with the corresponding operator. If the key does not contain an operator suffix, it returns an OperObject with the \"=\" operator. If the key is not a string, it throws an error.\n\nArguments\n\nx::Pair: A Pair object to be converted to an OperObject.\n\nReturns\n\nOperObject: An OperObject with the corresponding operator and values.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder._solve_field-Tuple{String, PormG.PormGModel, PormG.SQLInstruction}","page":"API","title":"PormG.QueryBuilder._solve_field","text":"This function checks if the given field is a valid field in the provided model. If the field is valid, it returns the field name, potentially modified based on certain conditions.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.bulk_insert-Tuple{PormG.SQLObjectHandler, DataFrames.DataFrame}","page":"API","title":"PormG.QueryBuilder.bulk_insert","text":"Inserts multiple rows into the database in bulk from a DataFrame.\n\nArguments\n\nobjct::SQLObjectHandler: The SQL object handler to use for the operation.\ndf::DataFrames.DataFrame: The DataFrame containing the data to be inserted.\ncolumns::Vector{Union{String, Pair{String, String}}}: Optional. Specifies the columns to insert and their mappings.\nchunk_size::Integer: Optional. The number of rows to insert in each batch (default: 1000).\nshow_query::Bool: Optional. If true, prints the generated SQL query (default: false).\ncopy::Bool: Optional. If true, creates a copy of the DataFrame before processing (default: false).\n\nExamples\n\n```julia   include(\"models.jl\")   import models as mdl\n\nBasic usage\n\nquery = mdl.User |> object   df = DataFrame(name=[\"Alice\", \"Bob\"], age=[30, 25])   bulk_insert(query, df)\n\nWith column mapping and excluding unwanted variables\n\nquery = mdl.Boook |> object   df = DataFrame(title=[\"Book A\", \"Book B\"], authorname=[\"Alice\", \"Bob\"], year=[2020, 2021], ignoreme=[\"x\", \"y\"])\n\nMap DataFrame column \"author_name\" to model field \"author\"\n\nExclude \"ignore_me\" by not including it in the columns argument\n\nbulkinsert(query, df, columns=[\"title\", \"year\", \"authorname\" => \"author\"])\n\nthe df will be modified to only include the columns \"title\", \"year\", and \"author_name\" (renamed to \"author\").\n\nIf you want to copy the DataFrame before processing, set copy=true:\n\nbulkinsert(query, df, columns=[\"title\", \"year\", \"authorname\" => \"author\"], copy=true)\n\n```\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.bulk_update-Tuple{PormG.SQLObjectHandler, DataFrames.DataFrame}","page":"API","title":"PormG.QueryBuilder.bulk_update","text":"Performs a bulk update operation on a database table using the provided DataFrame and a query object.\n\nArguments\n\nobjct::SQLObjectHandler: The database handler object.\ndf::DataFrames.DataFrame: The DataFrame containing the data to be used for the update.\ncolumns: (Optional) Specifies which columns to update. Can be a String, a Pair{String, String}, or a Vector of these. If nothing, no columns are specified.\nfilters: (Optional) Specifies the filters to apply for the update. Can be a String, a Pair{String, T} where T is String, Integer, Bool, Date, or DateTime, or a Vector of these. If nothing, no filters are applied.\nshow_query::Bool: (Optional) If true, prints the generated SQL query. Defaults to false.\nchunk_size::Integer: (Optional) Number of rows to process per chunk. Defaults to 1000.\n\nExample\n\n# Update the columns of the DataFrame df if df contains the primary key of the table\nbulk_update(objct, df)\n# Update the name and dof columns for the security_id in the DataFrame df\nbulk_update(objct, df, columns=[\"security_id\", \"name\", \"dof\"], filters=[\"security_id\"])\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.delete-Tuple{PormG.SQLObjectHandler}","page":"API","title":"PormG.QueryBuilder.delete","text":"Delete objects from the database with proper handling of foreign key relationships and cascading operations.\n\nArguments\n\nobjct::SQLObjectHandler: The SQL object handler containing the query and model information\nshow_query::Bool=false: If true, displays the generated SQL queries instead of executing them\nallow_delete_all::Bool=false: If true, allows deletion without WHERE clause filters (dangerous operation)\n\nReturns\n\nTuple{Integer, Dict{String, Integer}}: A tuple containing:\nTotal number of deleted objects\nDictionary mapping model names to their respective deletion counts\n\nBehavior\n\nValidates that the connection allows data modification operations\nRequires WHERE clause filters unless allow_delete_all is explicitly set to true\nHandles foreign key relationships by building a deletion dependency graph\nProcesses SETNULL, SETDEFAULT, and cascading delete operations appropriately\nExecutes all operations within a database transaction for data integrity\n\nExamples\n\n# Delete objects from a model with a specific filter\nquery = M.Status |> object\nquery.filter(\"status\" => \"Engine\")\ntotal, dict = delete(query)\n\n# Show the SQL query without executing it\nquery = M.Just_a_test_deletion |> object\nquery.filter(\"test_result__constructorid__name\" => \"Williams\")\ntotal, dict = delete(query, show_query = true)\n\n# Delete related tables (cascading delete)\nquery = M.Result |> object\nquery.filter(\"resultid\" => 1)\ntotal, dict = delete(query, show_query = false)\n\n# Delete all objects from a model (use with caution)\nquery = M.Just_a_test_deletion |> object\ntotal, dict = delete(query; allow_delete_all = true)\n\n\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.escape_like_pattern-Tuple{String}","page":"API","title":"PormG.QueryBuilder.escape_like_pattern","text":"Escape LIKE patterns to prevent wildcard injection\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.get_filter_query-Tuple{PormG.SQLObject, PormG.SQLInstruction}","page":"API","title":"PormG.QueryBuilder.get_filter_query","text":"getfilterquery(object::SQLObject, instruc::SQLInstruction)\n\nIterates over the filter of the object and generates the WHERE query for the given SQLInstruction object.\n\nALERT\n\nThis internal function is called by the build function.\n\nArguments\n\nobject::SQLObject: The object containing the filter to be selected.\ninstruc::SQLInstruction: The SQLInstruction object to which the WHERE query will be added.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.get_select_query-Tuple{Vector{Union{PormG.SQLTypeField, PormG.SQLTypeText}}, PormG.SQLInstruction}","page":"API","title":"PormG.QueryBuilder.get_select_query","text":"getselectquery(object::SQLObject, instruc::SQLInstruction)\n\nIterates over the values of the object and generates the SELECT query for the given SQLInstruction object.\n\nALERT\n\nThis internal function is called by the build function.\n\nArguments\n\nobject::SQLObject: The object containing the values to be selected.\ninstruc::SQLInstruction: The SQLInstruction object to which the SELECT query will be added.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.list-Tuple{PormG.SQLObjectHandler}","page":"API","title":"PormG.QueryBuilder.list","text":"Fetches a list of records from the database for the given SQLObjectHandler.\n\nReturns\n\nThe result of the database query as returned by fetch.\n\nExample\n\nquery = M.Result |> object\nquery.filter(\"raceid__year\" => 2020)\nquery.values(\"driverid__forename\", \"constructorid__name\", \"laps\" => Count(\"laps\"))\nquery.order_by(\"-laps\")\ndf = query |> list |> DataFrame\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.object-Tuple{PormG.PormGModel}","page":"API","title":"PormG.QueryBuilder.object","text":"Wraps a PormGModel into an ObjectHandler on which you can call:\n\n- .filter(...) to add WHERE clauses\n- .values(...) to choose/annotate columns\n- .order_by(...) to sort\n- .distinct() to add DISTINCT clause\n- .create(...) for single-row DML\n- .update(...) for single-row DML\n- plus bulk_insert, bulk_update, do_count, do_exists, list\n\nArguments\n\nmodel::PormGModel: The model to be wrapped and handled.\n\nExample\n\n```julia using PormG, DataFrames\n\nassume models loaded as M\n\nquery = M.User |> object\n\n1) Filtering & selecting\n\nquery.filter(\"is_active\" => true) query.values(\"id\", \"username\", \"email\") df = query |> list |> DataFrame\n\n2) Counting\n\nactiveusers = query |> docount\n\n3) Inserting a single row\n\nquery = M.Status |> object new = query.create(\"statusid\" => 42, \"status\" => \"Foo\")  \n\nreturns a Dict of the inserted row\n\n4) Updating a single row\n\nquery = M.Status |> object query.filter(\"statusid\" => 42) query.update(\"status\" => \"Bar\")\n\n5) Ordering & aggregation\n\nquery = M.Result |> object query.filter(\"raceidyear\" => 2020) query.values(   \"driveridforename\",    \"constructorid__name\",    \"laps\" => Count(\"laps\") ) query.order_by(\"-laps\") df2 = query |> list |> DataFrame\n\n6) Existence check\n\nquery = M.User |> object query.filter(\"id\" => 1) exists = query |> do_exists\n\n7) Bulk insert\n\ndfnew = DataFrame(name=[\"A\",\"B\"], age=[30,25]) bulkinsert(M.User |> object, df_new)\n\n8) Bulk update (by primary key)\n\ndfup = DataFrame(id=[1,2], name=[\"Alice\",\"Bob\"]) bulkupdate(M.User |> object, df_up, columns=[\"name\"], filters=[\"id\"]) ``\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.page-Tuple{PormG.SQLObjectHandler}","page":"API","title":"PormG.QueryBuilder.page","text":"Set pagination parameters for a SQL query object.\n\nArguments\n\nobject::SQLObjectHandler: The SQL object handler to modify\nlimit::Integer: Maximum number of records to return (default: 10)  \noffset::Integer: Number of records to skip from the beginning (default: 0)\n\nExamples\n\npage(query, limit=20, offset=10) |> list |> DataFrame or page(query, 20, 10) page(query, limit=20) |> list |> DataFrame or page(query, 20)\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.quote_identifier-Tuple{String, Any}","page":"API","title":"PormG.QueryBuilder.quote_identifier","text":"Quote SQL identifiers based on database type\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.safe_field_identifier-Tuple{String, PormG.PormGModel, Any}","page":"API","title":"PormG.QueryBuilder.safe_field_identifier","text":"Validate field name against model and return quoted identifier\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.safe_table_identifier-Tuple{String, Any}","page":"API","title":"PormG.QueryBuilder.safe_table_identifier","text":"Validate and quote table name\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.sanitize_identifier-Tuple{String, Vector{String}}","page":"API","title":"PormG.QueryBuilder.sanitize_identifier","text":"Sanitize SQL identifiers (table names, column names) to prevent injection. Only allows alphanumeric characters, underscores, and validates against model schema.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.up_values!-Tuple{PormG.SQLObject, NTuple{N, Union{Pair{String, T}, String, Symbol, PormG.SQLTypeField, PormG.SQLTypeFunction, PormG.SQLTypeText}} where {T<:PormG.SQLTypeFunction, N}}","page":"API","title":"PormG.QueryBuilder.up_values!","text":"Agora eu tenho que ver como que eu padronizo todas as variáveis para sair como SQLTypeField\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.QueryBuilder.FExpression","page":"API","title":"PormG.QueryBuilder.FExpression","text":"F object for direct database field references and operations (similar to Django F expressions).\n\nAllows you to reference database fields directly in operations without pulling data into Julia.\n\nExamples\n\n# Update a field with another field's value\nquery = MyModel |> object\nquery.filter(\"id\" => 1)\nquery.update(\"field1\" => F(\"field2\"))\n\n# Increment a field by a constant\nquery.update(\"counter\" => F(\"counter\") + 1)\n\n# Update with arithmetic operations between fields\nquery.update(\"total\" => F(\"price\") * F(\"quantity\"))\n\n# Use in filters to compare fields\nquery.filter(F(\"start_date\") <= F(\"end_date\"))\n\n# Use in annotations/values\nquery.values(\"price\", \"discounted_price\" => F(\"price\") * 0.9)\n\n\n\n\n\n","category":"type"},{"location":"api/#PormG.QueryBuilder.OperObject","page":"API","title":"PormG.QueryBuilder.OperObject","text":"Mutable struct representing an SQL operator object for using in the filter and annotate. That is a internal function, please do not use it.\n\nFields\n\noperator::String: the operator used in the SQL query.\nvalues::Union{String, Integer, Bool}: the value(s) to be used with the operator.\ncolumn::Union{String, SQLTypeFunction}: the column to be used with the operator.\n\n\n\n\n\n","category":"type"},{"location":"api/#PormG.Models.Model_to_str-Tuple{PormG.PormGModel, PormG.SQLConn}","page":"API","title":"PormG.Models.Model_to_str","text":"Converts a model object to a string representation to create the model.\n\nArguments\n\nModel_to_str(model::Union{Model_Type, PormGModel}; contants_julia::Vector{String}=reserved_words)::String\n\nmodel::Union{Model_Type, PormGModel}: The model object to convert.\ncontants_julia::Vector{String}=reserved_words: A vector of reserved words in Julia.\n\nReturns\n\nString: The string representation of the model object.\n\nExamples\n\nusers = Models.Model(\"users\", \n  name = Models.CharField(), \n  email = Models.CharField(), \n  age = Models.IntegerField()\n)\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.Models.are_model_fields_equal-Tuple{PormG.PormGModel, PormG.PormGModel}","page":"API","title":"PormG.Models.are_model_fields_equal","text":"aremodelfieldsequal(newmodel::PormGModel, old_model::PormGModel) :: Bool\n\nCompares the fields of two PormGModel instances to determine if they are equal.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.Models.format_string-Tuple{Any}","page":"API","title":"PormG.Models.format_string","text":"format_string(x)\n\nFormat the input x as a string if it is of type String, otherwise return x as is.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.Models.get_all_models-Tuple{Module}","page":"API","title":"PormG.Models.get_all_models","text":"Returns a vector containing all the models defined in the given module.\n\nArguments\n\nget_all_models(modules::Module; symbol::Bool=false)::Vector{Union{Symbol, PormGModel}}\n\nmodules::Module: The module to search for models.\nsymbol::Bool=false: If true, returns the model names as symbols. If false, returns the model instances.\n\nReturns\n\nA vector containing all the models defined in the module.\n\n\n\n\n\n","category":"method"},{"location":"api/#PormG.Models.validate_default-Tuple{Any, Type, String, Function}","page":"API","title":"PormG.Models.validate_default","text":"validatedefault(default, expectedtype::Type, field_name::String, converter::Function)\n\nValidate the default value for a field based on the expected type.\n\nArguments\n\ndefault: The default value to be validated.\nexpected_type::Type: The expected type for the default value.\nfield_name::String: The name of the field being validated.\nconverter::Function: A function used to convert the default value if it is not of the expected type.\n\nReturns\n\nIf the default value is of the expected type, it is returned as is.\nIf the default value can be converted to the expected type using the provided converter function, the converted value is returned.\nIf the default value is neither of the expected type nor convertible to it, an ArgumentError is thrown.\n\n\n\n\n\n","category":"method"},{"location":"#PormG-Documentation","page":"Home","title":"PormG Documentation","text":"","category":"section"},{"location":"#Overview","page":"Home","title":"Overview","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"PormG is a Julia package designed to facilitate SQL operations, model management, and migrations. It provides a set of abstract types and functions that allow users to interact with databases in a structured and efficient manner.","category":"page"},{"location":"#Installation","page":"Home","title":"Installation","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"To install PormG, you can use the Julia package manager. Open the Julia REPL and run the following command:","category":"page"},{"location":"","page":"Home","title":"Home","text":"using Pkg\nPkg.add(\"PormG\")","category":"page"},{"location":"#Usage","page":"Home","title":"Usage","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"Once installed, you can use PormG in your Julia projects by importing the module:","category":"page"},{"location":"","page":"Home","title":"Home","text":"using PormG","category":"page"},{"location":"#Example","page":"Home","title":"Example","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"Here is a simple example of how to use PormG to perform a database operation:","category":"page"},{"location":"","page":"Home","title":"Home","text":"# Example code demonstrating usage","category":"page"},{"location":"","page":"Home","title":"Home","text":"For more detailed usage instructions and examples, please refer to the API documentation.","category":"page"},{"location":"#Contributing","page":"Home","title":"Contributing","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"Contributions to PormG are welcome! If you would like to contribute, please fork the repository and submit a pull request.","category":"page"},{"location":"#License","page":"Home","title":"License","text":"","category":"section"},{"location":"","page":"Home","title":"Home","text":"PormG is licensed under the MIT License. See the LICENSE file for more details.","category":"page"}]
